{
  "category_edits": [
    {
      "category": "hyperparameter_tuning",
      "rationale": "Across all four datasets, increase convolution depth from six to eight blocks, raise dropout to 0.2 to regularize the added capacity, and raise learning rate to 1e-3 to accelerate fitting. Retain history length 64, hidden size 64, existing features, tied embeddings, scoring, readout, pointwise loss and Adam optimizer. Existing checkpoint metadata and predictor construction already synchronize block count. Preserve one checkpoint per category, seeds and training limits; require the supplied data directory.",
      "edits": [
        {
          "find": "NUM_BLOCKS    = int(os.environ.get(\"NEXTITNET_BLOCKS\", \"6\"))",
          "replace": "NUM_BLOCKS    = int(os.environ.get(\"NEXTITNET_BLOCKS\", \"8\"))"
        },
        {
          "find": "DROPOUT_RATE  = float(os.environ.get(\"NEXTITNET_DROPOUT\", \"0.15\"))",
          "replace": "DROPOUT_RATE  = float(os.environ.get(\"NEXTITNET_DROPOUT\", \"0.2\"))"
        },
        {
          "find": "LR            = float(os.environ.get(\"NEXTITNET_LR\", \"8e-4\"))",
          "replace": "LR            = float(os.environ.get(\"NEXTITNET_LR\", \"1e-3\"))"
        },
        {
          "find": "DATA_DIR = os.environ.get(\"GAGC_DATA_DIR\", \"./input/trainval\")",
          "replace": "DATA_DIR = os.environ['GAGC_DATA_DIR']"
        }
      ]
    }
  ],
  "change_summary": "Jointly tune NextItNet to eight blocks, dropout 0.2 and learning rate 1e-3 across all four category models. Existing metadata keeps prediction checkpoint-compatible. Require GAGC_DATA_DIR."
}
